changeSet.sql:
ALTER TABLE transactions
    ADD COLUMN withdrawn_at      timestamp(6) with time zone,
    ADD COLUMN withdrawal_reason varchar(500);
COMMENT ON COLUMN transactions.withdrawn_at IS
    'When the buyer withdrew from their instalment plan (status WITHDRAWN). Null otherwise.';

ALTER TABLE payments
    ADD COLUMN refund_amount numeric(19, 2),
    ADD COLUMN refund_reason varchar(500),
    ADD CONSTRAINT chk_payments_refund_amount
        CHECK (refund_amount IS NULL OR (refund_amount > 0 AND refund_amount <= amount));
COMMENT ON COLUMN payments.refund_amount IS
    'How much of this payment is owed back, once refund_requested_at is set; null = all of it. Part of it on a plan withdrawal: the developer keeps their declared share.';

DROP INDEX uq_refunds_one_live_per_payment;
CREATE UNIQUE INDEX uq_refunds_one_in_flight_per_payment ON refunds (payment_id)
    WHERE status NOT IN ('FAILED', 'PROCESSED') AND deleted = false;
COMMENT ON TABLE refunds IS
    'Money returned to a buyer for a payment. One refund in flight per payment (unique index); a payment may be refunded in parts, never beyond what is owed (the service checks). Never deleted. See AGENTS.md, "Payments".';

ALTER TABLE owned_plots DROP CONSTRAINT chk_owned_plots_status;
ALTER TABLE owned_plots ADD CONSTRAINT chk_owned_plots_status CHECK (status IN (
    'RESERVED', 'PENDING_VERIFICATION', 'ALLOCATED', 'INSTALLMENT_ACTIVE', 'COMPLETED',
    'IN_ARREARS', 'UPGRADE_PENDING', 'TRANSFERRED', 'SUPERSEDED', 'WITHDRAWN'));
DROP INDEX uq_owned_plots_one_owner;
CREATE UNIQUE INDEX uq_owned_plots_one_owner ON owned_plots (plot_id)
    WHERE deleted = false AND status NOT IN ('TRANSFERRED', 'SUPERSEDED', 'WITHDRAWN');

CREATE FUNCTION landvault_release_withdrawn_plot(p_transaction_id uuid, p_actor varchar)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_plot_id   uuid;
    v_restore   varchar;
    v_tier_type varchar;
    v_tier_size numeric;
BEGIN
    SELECT t.plot_id, r.previous_plot_status
      INTO v_plot_id, v_restore
      FROM transactions t
      JOIN reservations r ON r.id = t.reservation_id
     WHERE t.id = p_transaction_id
       AND t.status = 'WITHDRAWN';
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    IF v_restore NOT IN ('AVAILABLE_DEV', 'AVAILABLE_INV') THEN
        RAISE EXCEPTION 'landvault_release_withdrawn_plot: refusing to set plot status to %', v_restore;
    END IF;

    -- As 060: the tier row's lock, so a size edit in flight is seen.
    SELECT pt.tier_type, pt.size_sqm
      INTO v_tier_type, v_tier_size
      FROM plots p
      JOIN price_tiers pt ON pt.id = p.price_tier_id
     WHERE p.id = v_plot_id
       FOR SHARE OF pt;

    UPDATE plots p
       SET status = v_restore,
           nominal_size_sqm = CASE WHEN v_tier_type = 'LAND_SIZE'
                                   THEN v_tier_size
                                   ELSE p.nominal_size_sqm END,
           updated_at = now(),
           updated_by = p_actor
     WHERE p.id = v_plot_id
       AND p.deleted = false
       AND p.status = 'ON_PLAN';

    RETURN FOUND;
END;
$$;

REVOKE ALL ON FUNCTION landvault_release_withdrawn_plot(uuid, varchar) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION landvault_release_withdrawn_plot(uuid, varchar) TO ${appDbUsername};

changeSet.rollback:
DROP FUNCTION landvault_release_withdrawn_plot(uuid, varchar);
DROP INDEX uq_owned_plots_one_owner;
CREATE UNIQUE INDEX uq_owned_plots_one_owner ON owned_plots (plot_id)
    WHERE deleted = false AND status NOT IN ('TRANSFERRED', 'SUPERSEDED');
ALTER TABLE owned_plots DROP CONSTRAINT chk_owned_plots_status;
ALTER TABLE owned_plots ADD CONSTRAINT chk_owned_plots_status CHECK (status IN (
    'RESERVED', 'PENDING_VERIFICATION', 'ALLOCATED', 'INSTALLMENT_ACTIVE', 'COMPLETED',
    'IN_ARREARS', 'UPGRADE_PENDING', 'TRANSFERRED', 'SUPERSEDED'));
DROP INDEX uq_refunds_one_in_flight_per_payment;
CREATE UNIQUE INDEX uq_refunds_one_live_per_payment ON refunds (payment_id)
    WHERE status <> 'FAILED' AND deleted = false;
ALTER TABLE payments DROP CONSTRAINT chk_payments_refund_amount;
ALTER TABLE payments DROP COLUMN refund_reason, DROP COLUMN refund_amount;
ALTER TABLE transactions DROP COLUMN withdrawal_reason, DROP COLUMN withdrawn_at;
